import{_ as e,o as d,c as o,a2 as r}from"./chunks/framework.DHtetOlu.js";const q=JSON.parse('{"title":"API reference","description":"","frontmatter":{},"headers":[],"relativePath":"en/scripting/api.md","filePath":"en/scripting/api.md"}'),c={name:"en/scripting/api.md"};function a(i,t,n,s,u,l){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="api-reference" tabindex="-1">API reference <a class="header-anchor" href="#api-reference" aria-label="Permalink to &quot;API reference&quot;">​</a></h1><p>The <a href="./console.html">console</a> commands, grouped by object. Arguments in brackets are optional. Ids are strings (<code>&quot;l3&quot;</code>, <code>&quot;p5&quot;</code>, <code>&quot;n2&quot;</code>); wherever an id is expected, the <strong>name</strong> given to the entity or node also works, and <code>getid(&quot;name&quot;)</code> returns the id. Many commands that create something accept <code>id=</code> (to set the id) and <code>name=</code>.</p><h2 id="geometry-—-g" tabindex="-1">Geometry — <code>g</code> <a class="header-anchor" href="#geometry-—-g" aria-label="Permalink to &quot;Geometry — `g`&quot;">​</a></h2><h3 id="entities" tabindex="-1">Entities <a class="header-anchor" href="#entities" aria-label="Permalink to &quot;Entities&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>Description</th></tr></thead><tbody><tr><td><code>g.point((x, y))</code></td><td>point</td></tr><tr><td><code>g.line(a, b, construction=False)</code></td><td>line; <code>a</code> and <code>b</code> are coordinates or point ids</td></tr><tr><td><code>g.circle(center, r=5)</code></td><td>circle</td></tr><tr><td><code>g.arc(center, start, end)</code></td><td>counterclockwise arc from <code>start</code> to <code>end</code></td></tr><tr><td><code>g.rectangle(corner, opposite)</code></td><td>rectangle (grouped, with H/V)</td></tr><tr><td><code>g.rectangle_center(center, corner)</code></td><td>rectangle symmetric about the center</td></tr></tbody></table><h3 id="constraints" tabindex="-1">Constraints <a class="header-anchor" href="#constraints" aria-label="Permalink to &quot;Constraints&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>Description</th></tr></thead><tbody><tr><td><code>g.horizontal(l)</code>, <code>g.vertical(l)</code></td><td>horizontal/vertical line (or two points)</td></tr><tr><td><code>g.parallel(a, b)</code>, <code>g.perpendicular(a, b)</code></td><td>two lines</td></tr><tr><td><code>g.tangent(a, b)</code></td><td>line and arc/circle, or two arcs/circles</td></tr><tr><td><code>g.equal(a, b)</code></td><td>equal lengths or radii</td></tr><tr><td><code>g.coincident(a, b)</code></td><td>two points at the same place</td></tr><tr><td><code>g.point_on(p, curve)</code></td><td>point on the curve</td></tr><tr><td><code>g.midpoint(p, l)</code></td><td>point at the middle of the line</td></tr><tr><td><code>g.symmetric(p1, p2, axis=&quot;y&quot; | line)</code></td><td>points symmetric about an axis</td></tr><tr><td><code>g.concentric(c1, c2)</code></td><td>same center</td></tr><tr><td><code>g.fix(p)</code>, <code>g.unfix(p)</code></td><td>pins/unpins a point</td></tr><tr><td><code>g.detach(&quot;O&quot;)</code></td><td>frees curves attached to the Origin itself (older drawings)</td></tr></tbody></table><h3 id="dimensions-and-variables" tabindex="-1">Dimensions and variables <a class="header-anchor" href="#dimensions-and-variables" aria-label="Permalink to &quot;Dimensions and variables&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>Description</th></tr></thead><tbody><tr><td><code>g.distance(a, [b,] &quot;50 mm&quot;)</code></td><td>distance (line, two points or point-line)</td></tr><tr><td><code>g.hdistance(a, b, &quot;10 mm&quot;)</code>, <code>g.vdistance(a, b, &quot;10 mm&quot;)</code></td><td>horizontal/vertical distance</td></tr><tr><td><code>g.radius(c, &quot;L/2&quot;)</code>, <code>g.diameter(c, 10)</code></td><td>radius and diameter</td></tr><tr><td><code>g.angle(l1, l2, &quot;30 deg&quot;)</code></td><td>angle between lines</td></tr><tr><td><code>g.set_dimension(&quot;k5&quot;, &quot;g*2&quot;)</code></td><td>changes a dimension value (or expression)</td></tr><tr><td><code>g.value(&quot;k5&quot;)</code></td><td>current value of a dimension</td></tr><tr><td><code>g.var(&quot;g&quot;, &quot;0.5 mm&quot;)</code></td><td>creates or changes a variable</td></tr><tr><td><code>g.del_var(&quot;g&quot;)</code>, <code>g.rename_var(&quot;g&quot;, &quot;gap&quot;)</code></td><td>deletes and renames variables</td></tr></tbody></table><h3 id="editing" tabindex="-1">Editing <a class="header-anchor" href="#editing" aria-label="Permalink to &quot;Editing&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>Description</th></tr></thead><tbody><tr><td><code>g.trim(curve, (x, y))</code></td><td>trim: removes the piece of the curve containing the point</td></tr><tr><td><code>g.delete(ids...)</code></td><td>deletes</td></tr><tr><td><code>g.rename(id, &quot;name&quot;)</code></td><td>names an entity</td></tr><tr><td><code>g.move(p, (x, y))</code></td><td>moves a point</td></tr><tr><td><code>g.translate(ids, dx=5, dy=0)</code></td><td>translates</td></tr><tr><td><code>g.rotate(ids, &quot;15 deg&quot;, pivot=(0, 0))</code></td><td>rotates</td></tr><tr><td><code>g.set_radius(c, 5)</code></td><td>changes the radius</td></tr><tr><td><code>g.construction(ids, True)</code></td><td>marks as construction</td></tr><tr><td><code>g.offset(ids, &quot;2 mm&quot;)</code>, <code>g.set_offset(g, &quot;-5 mm&quot;)</code></td><td>associative offset and its distance</td></tr><tr><td><code>g.mirror(ids, axis=&quot;y&quot;)</code></td><td>associative mirror (axis <code>&quot;x&quot;</code>, <code>&quot;y&quot;</code> or a line)</td></tr><tr><td><code>g.array(ids, nx=3, ny=1, dx=&quot;20 mm&quot;, dy=0)</code></td><td>linear pattern</td></tr><tr><td><code>g.array_circular(ids, n=6, angle=&quot;360 deg&quot;, center=(0, 0))</code></td><td>circular pattern</td></tr><tr><td><code>g.set_pattern(g, nx=4, dx=&quot;25 mm&quot;)</code></td><td>changes a pattern</td></tr><tr><td><code>g.group([ids], name=&quot;rotor&quot;)</code>, <code>g.ungroup(g)</code></td><td>groups and ungroups</td></tr><tr><td><code>g.hide(g)</code>, <code>g.show(g)</code></td><td>hides and shows a group</td></tr></tbody></table><h3 id="queries-and-problem" tabindex="-1">Queries and problem <a class="header-anchor" href="#queries-and-problem" aria-label="Permalink to &quot;Queries and problem&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>Returns / does</th></tr></thead><tbody><tr><td><code>g.get(id)</code></td><td>the entity (dictionary)</td></tr><tr><td><code>g.list()</code></td><td>list of ids</td></tr><tr><td><code>g.measure(a, b)</code></td><td>minimum distance between two entities</td></tr><tr><td><code>g.area(ids)</code></td><td>area enclosed by the curves</td></tr><tr><td><code>g.dof()</code></td><td>remaining degrees of freedom</td></tr><tr><td><code>g.units(&quot;mm&quot;)</code></td><td>project length unit</td></tr><tr><td><code>g.problem(&quot;planar&quot; | &quot;axisymmetric&quot;, depth=&quot;100 mm&quot;)</code></td><td>problem type and depth (planar)</td></tr></tbody></table><h2 id="mesh-—-m" tabindex="-1">Mesh — <code>m</code> <a class="header-anchor" href="#mesh-—-m" aria-label="Permalink to &quot;Mesh — `m`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Description</th></tr></thead><tbody><tr><td><code>m.material(&quot;Copper&quot;, mur=1, sigma=58, br=0, color=&quot;#e0914f&quot;, bh=[(H, B), ...], kh=, alpha=, ke=, group=)</code></td><td>creates or edits a material (σ in MS/m, Br in T; <code>bh=None</code> removes the curve)</td></tr><tr><td><code>m.del_material(name)</code>, <code>m.duplicate_material(name)</code>, <code>m.restore_material(name)</code></td><td>deletes, duplicates and restores the default</td></tr><tr><td><code>m.circuit(&quot;Coil&quot;, current=&quot;10&quot;)</code></td><td>creates or edits a circuit</td></tr><tr><td><code>m.del_circuit(&quot;Coil&quot;)</code></td><td>deletes</td></tr><tr><td><code>m.region((x, y), name=, material=, circuit=, current=, turns=, angle=, label=(dx, dy))</code></td><td>assigns to the region containing the point; returns the area</td></tr><tr><td><code>m.regions()</code></td><td>list <code>[((x, y), area, material)]</code></td></tr><tr><td><code>m.boundary_def(&quot;Name&quot;, type=, value=, a1=, a2=, c0=, c1=, color=)</code></td><td>creates or edits a boundary</td></tr><tr><td><code>m.boundary([&quot;l1&quot;, &quot;l2&quot;], &quot;Name&quot; | &quot;dirichlet&quot; | &quot;neumann&quot; | &quot;periodic&quot; | &quot;antiperiodic&quot; | None)</code></td><td>applies a boundary to the curves</td></tr><tr><td><code>m.mesh_size((x, y), &quot;0.5 mm&quot; | &quot;auto&quot;)</code></td><td>element size in the region</td></tr><tr><td><code>m.curve_size([curves], &quot;1 mm&quot;)</code></td><td>size along curves (<code>None</code> removes it)</td></tr><tr><td><code>m.settings(&quot;n1&quot;, size=&quot;2 mm&quot; | &quot;auto&quot;, min_angle=30)</code></td><td>default size and mesh quality</td></tr><tr><td><code>m.generate(&quot;n1&quot;)</code></td><td>generates the mesh</td></tr><tr><td><code>m.add(name=&quot;Mesh&quot;)</code>, <code>m.rename(id, name)</code>, <code>m.remove(id)</code></td><td>mesh nodes</td></tr></tbody></table><p>Boundary types for <code>type=</code>: <code>dirichlet</code> (A = value + a1·x + a2·y), <code>neumann</code>, <code>mixed</code> (c0, c1), <code>periodic</code>, <code>antiperiodic</code>.</p><h2 id="solver-—-s" tabindex="-1">Solver — <code>s</code> <a class="header-anchor" href="#solver-—-s" aria-label="Permalink to &quot;Solver — `s`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Description</th></tr></thead><tbody><tr><td><code>s.add_physics(name=&quot;Magnetic field&quot;, circuit=False)</code></td><td>new physics (field, or circuit with <code>circuit=True</code>)</td></tr><tr><td><code>s.physics(&quot;n2&quot;, analysis=&quot;magnetostatic&quot; | &quot;harmonic&quot; | &quot;transient&quot;, frequency=, dt=, t_end=, schematic=)</code></td><td>sets the analysis (frequency in Hz, times in s)</td></tr><tr><td><code>s.solve(&quot;n2&quot;)</code></td><td>solves (generating the mesh first if needed)</td></tr><tr><td><code>s.rename(id, name)</code>, <code>s.remove(id)</code></td><td>organization</td></tr></tbody></table><h2 id="results-—-r" tabindex="-1">Results — <code>r</code> <a class="header-anchor" href="#results-—-r" aria-label="Permalink to &quot;Results — `r`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Description</th></tr></thead><tbody><tr><td><code>r.view(&quot;n2&quot;, name=)</code></td><td>new field view</td></tr><tr><td><code>r.interpolate(&quot;n2&quot;, level=3)</code></td><td>interpolated view (1 to 6)</td></tr><tr><td><code>r.plot(view, &quot;surface&quot; | &quot;contour&quot; | &quot;arrow&quot; | &quot;line&quot;, quantity=&quot;b&quot; | &quot;h&quot; | &quot;a&quot; | &quot;j&quot; | &quot;bn&quot; | &quot;bt&quot;)</code></td><td>layer in a view (or plot over line)</td></tr><tr><td><code>r.show(id, visible=, range=(0, 1.5), n_lines=20, spacing=, scale=, curve=, quantity=, color=, color_by_value=, colormap=, regions=[(x, y)], outputs=[(&quot;fx&quot;, &quot;Fx&quot;)], var_name=, expr=, unit_label=, at_time=, legend=(x, y, s))</code></td><td>options of a layer or item</td></tr><tr><td><code>r.table(&quot;n2&quot;, name=)</code></td><td>new table</td></tr><tr><td><code>r.item(table, &quot;circuits&quot; | &quot;lineint&quot; | &quot;surfint&quot; | &quot;formula&quot;, name=)</code></td><td>table item</td></tr><tr><td><code>r.move(layer, view)</code>, <code>r.duplicate(id)</code>, <code>r.rename(id, name)</code>, <code>r.remove(id)</code></td><td>organization</td></tr><tr><td><code>r.result(&quot;Fx&quot;, physics=&quot;n2&quot;)</code></td><td>number of a result variable (at the shown instant, in transient)</td></tr><tr><td><code>r.results(&quot;n2&quot;)</code></td><td>list <code>[(name, value, unit), ...]</code></td></tr><tr><td><code>r.series(&quot;Coil_I&quot;)</code></td><td>transient: <code>(times in s, values)</code></td></tr></tbody></table><p>Integral quantities (for <code>outputs=</code>): surface — <code>area</code>, <code>volume</code>, <code>intA</code>, <code>current</code>, <code>energy</code>, <code>bavg</code>, <code>b2</code>, <code>loss</code>, <code>ironLoss</code>, <code>fx</code>, <code>fy</code>, <code>torque</code>; line — <code>length</code>, <code>flux</code>, <code>mmf</code>, <code>intB</code>, <code>intBn</code>, <code>bavg</code>, <code>fx</code>, <code>fy</code>, <code>torque</code>. All in SI units.</p><h2 id="schematic-—-c" tabindex="-1">Schematic — <code>c</code> <a class="header-anchor" href="#schematic-—-c" aria-label="Permalink to &quot;Schematic — `c`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Description</th></tr></thead><tbody><tr><td><code>c.add(name=&quot;Circuit 1&quot;)</code></td><td>new schematic</td></tr><tr><td><code>c.part(sch, &quot;V&quot; | &quot;I&quot; | &quot;R&quot; | &quot;L&quot; | &quot;C&quot; | &quot;gnd&quot; | &quot;coil&quot;, x=, y=, rot=, value=, amp=, freq=, phase=, dc=, circuit=)</code></td><td>component</td></tr><tr><td><code>c.wire(sch, (part, terminal), (part, terminal), mid=)</code></td><td>wire between terminals</td></tr><tr><td><code>c.route(wire, x)</code> or <code>c.route(wire, y=80)</code></td><td>wire route</td></tr><tr><td><code>c.set(part, value=, name=)</code>, <code>c.move(part, (x, y))</code>, <code>c.rotate(part)</code>, <code>c.remove(part)</code></td><td>editing</td></tr></tbody></table><h2 id="globals" tabindex="-1">Globals <a class="header-anchor" href="#globals" aria-label="Permalink to &quot;Globals&quot;">​</a></h2><p><code>help()</code>, <code>getid(&quot;name&quot;)</code>, <code>undo()</code>, <code>redo()</code>, <code>fit()</code>, <code>reset()</code>. <code>clear()</code> and <code>next_id(n)</code> appear in the exported script.</p>',25)])])}const h=e(c,[["render",a]]);export{q as __pageData,h as default};
